import {scenes,structures,diagnostic,stages,sentence} from './data.js';
import {evidenceFor} from './logic.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icon=(name,color='blue')=>`<img class="icon" src="../ios-assets/${name}-${color}.png" width="20" height="20" alt="">`;
export const btn=(label,action,style='primary',extra='')=>`<button class="${style}" data-action="${action}" ${extra}>${label}</button>`;
const header=(title,description,tools='')=>`<div class="page-header"><div><h1>${title}</h1><p>${description}</p></div>${tools}</div>`;
const formula=modal=>`<strong>${modal}</strong> + 主语 + <strong>动词原形</strong> + … ?`;
export function today(state,scene){
 const supported=state.support==='independent';const diagnosedIndependent=state.diagnosticSupport==='independent';const inProgress=state.session&&state.session.step<6;
 const reason=state.diagnostic.length?(diagnosedIndependent?'摸底中，你识别了请求句的结构，也独立写出了一个请求。今天先增加新情境的练习。':'摸底对请求句的证据还不充分。今天保留关键词与逐步提示，先把问句语序和动词原形用稳。'):'还没有足够的作答证据。先从短请求句试学，或者用 4 分钟摸底确定支架多少。';
 return `<section>${header('今天，练会一个句型。','场景你来选，语法一步步用稳。每天 24 分钟，有明确的开始和结束。','<span class="date">10月10日 · 周六</span>')}
 <div class="scene-strip"><span class="small muted">今天在哪儿用？</span>${scenes.map(s=>`<button class="scene-chip ${s.id===scene.id?'selected':''}" aria-pressed="${s.id===scene.id}" data-action="quick-scene" data-id="${s.id}">${s.name}</button>`).join('')}${state.customScenes.map(s=>`<button class="scene-chip ${s.id===scene.id?'selected':''}" aria-pressed="${s.id===scene.id}" data-action="quick-scene" data-id="${s.id}">${esc(s.name)}</button>`).join('')}<a class="text-button" href="#scenes">自定义场景 ${icon('arrow.up.right')}</a></div>
 <div class="lesson-block"><div class="lesson-main"><div class="row-between"><span class="tag accent">${esc(scene.name)} · ${esc(scene.topic)}</span><span class="small muted">同一句型，继续练</span></div><h2>礼貌地提出一个请求</h2><div class="formula">${formula(state.modal)}</div><div class="example"><p class="english">${esc(sentence(scene,state.modal))}</p><p class="muted">${esc(scene.meaning)}</p></div><div class="lesson-actions">${btn(inProgress?'继续本次学习':'开始 24 分钟学习','start-session')}${inProgress?btn('重新开始','restart-session','text-button'):''}${btn(state.diagnostic.length?'重新摸底':'先做 4 分钟摸底','diagnostic','text-button')}</div></div>
 <aside class="lesson-reason"><h3>为什么今天练这个？</h3><p class="small muted">${reason}</p>${state.supportSource==='manual'?'<p class="small blue">当前支架由你手动调整；已有摸底结论保持不变。</p>':''}${inProgress?`<p class="small blue">当前练习：${esc([...scenes,...state.customScenes].find(s=>s.id===state.session.sceneId)?.name)}。更换场景用于下一次练习。</p>`:''}<div class="reason-step"><span>1</span><div>抓住一个结构<p>问句语序 + 动词原形</p></div></div><div class="reason-step"><span>2</span><div>放到你的场景<p>${esc(scene.goal)}</p></div></div><div class="reason-step"><span>3</span><div>换个地方独立用<p>检验句型，不只是记住原句</p></div></div><div class="row-between"><span class="small muted">练习支架</span><span class="tag">${supported?'独立尝试':'逐步提示'}</span></div></aside></div>
 <div class="plan"><div class="row-between plan-heading"><h2>今天的 24 分钟</h2><span class="small muted">首次摸底替代复习，不加时</span></div><div class="plan-steps">${[['arrow.clockwise','复习 / 摸底','4 分钟','先确定哪些还没用稳。'],['headphones','句中学词','8 分钟','听懂意思，拆开句型再组回去。'],['text.bubble','说与写','8 分钟','撤掉示范，用到自己的表达里。'],['checkmark.circle.fill','迁移检验','4 分钟','换新情境，再独立组织一句。']].map(([i,h,t,p])=>`<div class="plan-step"><div class="row">${icon(i,'muted')}<h3>${h}</h3><span class="time">${t}</span></div><p>${p}</p></div>`).join('')}</div></div>
 <div class="lower-grid"><div class="lower-panel"><div class="row-between"><h2>你的学习起点</h2><a class="text-button" href="#profile">查看依据</a></div><p class="small muted">${state.diagnostic.length?'理解与产出分别记录；口语仍待评估。':'没有把你预先标为 A1 或 A2。用作答建立起点。'}</p><div class="small-line"><span>当前请求句</span><span>${supported?'独立尝试':'有支架练习'}</span></div><div class="small-line"><span>难度不合适？</span><div class="row">${btn('太简单','less-support','text-button')}${btn('需要提示','more-support','text-button')}</div></div></div><div class="lower-panel"><h2>场景可以换，学习线索留下来</h2><p class="small muted">你在公司练过的请求句，会在学校、机场继续出现。能认得、能独立用、换场景仍能用，分别留下证据。</p><a class="text-button" href="#structures">看看语法与句型路线 ${icon('arrow.right')}</a></div></div>${state.notice?`<p class="form-status" role="status">${esc(state.notice)}</p>`:''}</section>`;
}
export function sceneView(state,scene){return `<section>${header('在哪儿用，你来决定。','先选真实场景，再让同一个语法与句型服务于你的任务。')}
 <div class="scene-layout"><div><h2 class="scene-list-title">常用场景</h2><div class="scene-list">${[...scenes,...state.customScenes].map(s=>`<button class="scene-option ${s.id===scene.id?'selected':''}" data-action="preview-scene" data-id="${s.id}" aria-pressed="${s.id===scene.id}"><span class="scene-symbol">${icon(s.icon,s.id===scene.id?'blue':'muted')}</span><span><h3>${esc(s.name)}</h3><p>${esc(s.topic)}</p><small>${s.id===state.sceneId?'当前使用':'继续练习同一个请求句型'}</small></span><span class="arrow" aria-hidden="true">${s.id===state.sceneId?'✓':'→'}</span></button>`).join('')}</div></div>
 <aside class="scene-preview"><span class="tag accent">场景预览 · ${esc(scene.name)}</span><h2>${esc(scene.goal)}</h2><p class="small muted">切换后仍练：${state.modal} you + 动词原形</p><div class="formula">${formula(state.modal)}</div><div class="preview-sentences"><p class="english">${esc(sentence(scene,state.modal))}<small>${esc(scene.meaning)}</small></p><p class="small muted">${scene.custom?'自定义情境先从所选请求任务开始，原型使用经整理的通用句型模板。':'每次最多聚焦 1 个句型和少量搭配，避免一换场景就突然变难。'}</p></div>${btn('使用这个场景','use-scene','primary',`data-id="${scene.id}"`)}</aside></div>
 <form class="custom-form" id="custom-form"><h2>也可以练你正在遇到的事</h2><p class="small muted">把「公司」细化成「请同事核对信息」，练习才会贴近你。</p><div class="form-grid"><label class="field">场景名称<input name="name" value="${esc(state.customDraft.name)}" required maxlength="16" placeholder="例如：办理酒店入住"></label><label class="field">对方是谁<input name="role" value="${esc(state.customDraft.role)}" required maxlength="30" placeholder="例如：酒店前台工作人员"></label><label class="field full">你要完成什么<textarea name="goal" required maxlength="120" rows="2" placeholder="例如：请前台帮我核对预订信息。">${esc(state.customDraft.goal)}</textarea></label><label class="field">先练哪一种请求？<select name="action"><option value="help">请求对方帮忙</option><option value="check" ${state.customDraft.action==='check'?'selected':''}>请求核对信息</option><option value="explain" ${state.customDraft.action==='explain'?'selected':''}>请求解释问题</option></select></label><div class="field"><span>会沿用的结构</span><p class="subtle-callout">${state.modal} you + 动词原形 + … ?</p></div></div><div class="row">${btn('保存并使用这个场景','save-custom','primary','type="submit"')}<span class="small muted">语法进度不会被重置</span></div><p class="form-status" id="custom-status" role="status"></p></form></section>`;}
export function structureView(state){return `<section>${header('先有结构，再能自由表达。','语法是学习主线。不同场景让同一结构被真正调用，而不是只换一批单词。')}<div class="subtle-callout"><strong>今天聚焦：请求句的语序与动词原形</strong><p>Can / Could you… 都能提出请求。本课的 could 是当下更委婉的请求，不是在讲过去。</p></div><div class="route-list">${structures.map((s,i)=>`<article class="route-item ${s.id==='request'?'active':''}"><span class="route-number">${String(i+1).padStart(2,'0')}</span><div><h2>${s.title}</h2><p>${s.grammar} · ${s.description}</p><p class="pattern">${s.pattern}</p></div>${btn(s.id==='request'?'练这个句型':'看内容','structure-detail','secondary',`data-id="${s.id}"`)}</article>`).join('')}</div><div class="structure-note"><h2>推进依据不是学完了多少节</h2><p>理解过 → 提示下用 → 本次独立用 → 新情境用 → 间隔后仍能用。每个阶段都有不同的作答证据。课程先检查相关前置结构；没用稳的地方插回复习。</p></div></section>`;}
const nodeStatus=rows=>!rows.length?['待摸底','还没有对应作答']:rows.some(r=>r.status==='review')?['需要再确认','本题出现了具体困难']:rows.some(r=>r.status==='unconfirmed')?['部分待确认','自由表达不凭单一答案判错']:rows.every(r=>r.status==='unmeasured')?['待评估','尚无有效对应证据']:['已有初步证据','本次作答符合预设表达'];
export function profileView(state){
 const body=state.diagnostic.length||state.practiceEvidence.length?`<div class="profile-layout"><div><table class="profile-table"><thead><tr><th>语法 / 技能</th><th>本次证据</th><th>下一步</th></tr></thead><tbody>${[['present','一般现在时'],['past','一般过去时'],['request','请求句'],['negation','否定与义务'],['listening','短句听力']].map(([id,n])=>{const rs=evidenceFor(state.diagnostic,id),[status,desc]=nodeStatus(rs);return `<tr><td><strong>${n}</strong><small>${desc}</small></td><td><span class="tag ${status==='已有初步证据'?'accent':''}">${status}</span><small>${rs.map(r=>`${r.dimension}：${r.status==='supported'?'本题通过':r.status==='review'?'待巩固':'待确认'}`).join('<br>')}</small></td><td>${rs.some(r=>r.status==='review')?'补一次短练习':'换个情境再确认'}</td></tr>`}).join('')}<tr><td><strong>口语</strong><small>文字作答不等于口语能力</small></td><td><span class="tag">待评估</span></td><td>后续接入确认后的语音任务</td></tr></tbody></table>${state.practiceEvidence.length?`<div class="results-list"><h2>最近的实际表达</h2>${state.practiceEvidence.map(e=>`<div class="result-row"><div><strong>${esc(e.scene)} · ${e.type}</strong><p>${esc(e.sentence)}</p></div><span class="tag accent">${esc(e.label)}</span></div>`).join('')}</div>`:''}</div><aside><div class="evidence-note"><h2>为什么不直接给你一个 A2？</h2><p>几道短题不足以判断完整的听说读写。这里先记录语法点和任务的实际表现，再在日常练习里补充证据。</p><p>理解、提示下表达、无提示表达和迁移能力分别记录。少量题的结果只用于确定起点。</p></div><div class="evidence-note"><h2>还需要什么证据？</h2><p>不同说话者的听力、真正的口头表达、未见情境，以及后续间隔复测。</p><span class="tag">间隔保持 · 待检验</span></div></aside></div>`:`<div class="empty-state"><h2>先看你怎样理解，也看你怎样表达。</h2><p>6 个短任务，约 4 分钟。先独立组织句子，再看结构与理解题。它只确定学习起点，不是 CEFR 认证测试。</p>${btn('开始快速摸底','diagnostic')}</div>`;
 return `<section>${header('水平，要从证据里看。','这是你的学习档案。一次答对算一次证据，稳定掌握需要后续检验。',btn('重新摸底','diagnostic','secondary'))}${body}</section>`;
}
export function diagnosticView(state){
 const d=state.diagnosticSession;
 if(!d)return `<section class="diagnostic-wrap">${header('用 4 分钟，找一个合适的起点。','先写一句，再做几道理解题。摸底替代今天的复习，不增加总时长。')}<div class="results-list">${[['独立表达','先观察你能否自己组织句子，避免刚看过示范。'],['理解与结构','再看主语、词形、语序和时间含义。'],['听懂关键信息','使用浏览器合成短音频；口语能力仍不评估。']].map(([a,b])=>`<div class="result-row"><div><h2>${a}</h2><p>${b}</p></div></div>`).join('')}</div><div class="practice-buttons">${btn('开始摸底','begin-diagnostic')}${btn('先从基础请求句试学','skip-diagnostic','secondary')}</div><p class="small muted" style="margin-top:20px">这是原型中的小样本观察，不直接换算 CEFR，不因未识别的自由表达判错。</p></section>`;
 if(d.index>=diagnostic.length){const independent=state.diagnosticSupport==='independent';return `<section class="diagnostic-wrap">${header('起点找到了，还会继续校正。',independent?'这次请求句的理解与文字产出都有初步证据，接下来试试跨场景独立使用。':'请求句还需要更多产出证据，接下来从有支架的问句结构开始。')}<div class="subtle-callout"><strong>学习建议：${independent?'独立尝试新情境':'先用短句与逐步提示'}</strong><p>口语仍待评估；未识别的自由表达留待确认。不会因为选择题答对，就跳过所有基础内容。</p></div><div class="results-list">${d.results.map(r=>`<div class="result-row"><div><strong>${r.dimension}</strong><p>${esc(r.note)}</p></div><span class="tag ${r.status==='supported'?'accent':''}">${r.status==='supported'?'本题通过':r.status==='review'?'待巩固':'待确认'}</span></div>`).join('')}</div><div class="practice-buttons">${btn('按这个起点继续学习','start-after-diagnostic')}${btn('查看学习档案','go-profile','secondary')}</div></section>`;}
 const q=diagnostic[d.index];return `<section class="diagnostic-wrap"><div class="session-header"><button class="text-button neutral" data-action="go-today">返回今日</button><span>快速摸底 · ${d.index+1} / ${diagnostic.length}</span></div><div class="diagnostic-progress"><span style="width:${d.index/diagnostic.length*100}%"></span></div><p class="question-label">${q.dimension}</p><h1>${q.title}</h1>${q.audio?`${btn(`${icon('play.fill','white')} 播放短音频`,'diagnostic-audio','primary','class="audio-button"')}<p class="small muted" style="margin-top:12px">${d.audioPlayed?'已播放完成；按照听到的信息作答。':d.audioPending?'正在播放，完成后才记录听力证据。':'播放后再选择；未听音频不会记为听力证据。'}</p>`:''}<p class="english" style="margin-top:24px">${q.prompt}</p>${q.options?`<div class="options">${q.options.map((o,i)=>`<button class="option" data-action="diagnostic-choice" data-id="${i}" aria-pressed="${d.selected===i}"><span class="radio-mark" aria-hidden="true"></span>${o}</button>`).join('')}</div>`:`<label class="field">你的英文表达<textarea id="diagnostic-answer" placeholder="${q.placeholder}" autocomplete="off">${esc(d.answer)}</textarea></label>`}<div class="practice-buttons">${btn(d.index===5?'完成，查看依据':'记录这题，继续','next-diagnostic','primary',q.options&&d.selected===null?'disabled':'')}${btn('暂时不会，先记录','skip-question','text-button')}</div><p class="form-status" role="status">${esc(state.notice)}</p></section>`;
}
